using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using NUnit.Framework;

namespace Bugsee.WrapperPolicy.Tests
{
    /// <summary>
    /// Links the managed Android bridge to the Android SDK it is pinned to. Unity resolves every
    /// AndroidJavaClass / AndroidJavaObject call by name and signature at run time, so a renamed or re-shaped SDK
    /// method is otherwise a device-only failure. The SDK side is a committed snapshot
    /// (Fixtures/android-sdk-api/&lt;version&gt;.txt, javap of the pinned AARs, regenerated by
    /// Tools~/scripts/update-android-api-manifest.sh), so the check runs without the SDK or a network.
    /// Checked: every com.bugsee.library class named in the C#; every CallStatic on an SDK class reaches a public static
    /// method of that name with a matching argument count (and matching primitive / string literal types); every
    /// Call on an instance names a method that exists in the SDK contracts or the JDK. Not checked (follow-up): the
    /// argument types of calls whose arguments are not literals, return types, and the UnityWrapper Java side
    /// (NativeBindingTests covers its arity).
    /// </summary>
    public class AndroidSdkBindingTests
    {
        static string RepoFile(string relative)
        {
            var dir = TestContext.CurrentContext.TestDirectory;
            while (!string.IsNullOrEmpty(dir))
            {
                if (File.Exists(Path.Combine(dir, "package.json")))
                    return Path.Combine(dir, relative);
                dir = Directory.GetParent(dir)?.FullName;
            }

            throw new InvalidOperationException("Could not locate repo root (package.json).");
        }

        static string StripComments(string s)
        {
            s = Regex.Replace(s, @"/\*.*?\*/", " ", RegexOptions.Singleline);
            return Regex.Replace(s, @"(?<![:""])//[^\n]*", " ");
        }

        sealed class JavaMethod
        {
            public string Name;
            public bool Static;
            public string[] Params;
            public bool VarArgs;

            public override string ToString() =>
                (Static ? "static " : "") + Name + "(" + string.Join(", ", Params) + ")";
        }

        sealed class JavaClass
        {
            public string Name;
            public bool IsEnum;
            public List<JavaMethod> Methods = new List<JavaMethod>();
        }

        static string[] SplitParams(string args)
        {
            var parts = new List<string>();
            int depth = 0, start = 0;
            for (int i = 0; i < args.Length; i++)
            {
                if (args[i] == '<') depth++;
                else if (args[i] == '>') depth--;
                else if (args[i] == ',' && depth == 0)
                {
                    parts.Add(args.Substring(start, i - start).Trim());
                    start = i + 1;
                }
            }

            var last = args.Substring(start).Trim();
            if (last.Length > 0) parts.Add(last);
            return parts.ToArray();
        }

        static Dictionary<string, JavaClass> _manifest;

        static string ManifestFile()
        {
            var version = Regex.Match(File.ReadAllText(RepoFile("Tools~/versions.env")), "ANDROID_SDK_VERSION=\"([^\"]+)\"").Groups[1].Value;
            Assert.That(version, Is.Not.Empty);
            var path = RepoFile("Tests~/WrapperPolicy/Fixtures/android-sdk-api/" + version + ".txt");
            Assert.That(File.Exists(path), Is.True,
                "No Android API snapshot for the pinned SDK " + version + ". Run Tools~/scripts/update-android-api-manifest.sh.");
            Assert.That(Directory.GetFiles(Path.GetDirectoryName(path), "*.txt").Length, Is.EqualTo(1),
                "Only the snapshot of the pinned SDK is kept; rerun Tools~/scripts/update-android-api-manifest.sh.");
            return path;
        }

        static Dictionary<string, JavaClass> Manifest()
        {
            if (_manifest != null) return _manifest;
            var classes = new Dictionary<string, JavaClass>();
            JavaClass current = null;
            foreach (var raw in File.ReadAllLines(ManifestFile()))
            {
                if (raw.StartsWith("#") || raw.Trim().Length == 0 || raw.Trim() == "}") continue;
                if (!raw.StartsWith(" "))
                {
                    var header = Regex.Match(raw, @"\b(class|interface|enum)\s+([\w.$]+)");
                    Assert.That(header.Success, Is.True, "Unparsed snapshot line: " + raw);
                    current = new JavaClass { Name = header.Groups[2].Value, IsEnum = header.Groups[1].Value == "enum" || raw.Contains("extends java.lang.Enum<") };
                    classes[current.Name] = current;
                    continue;
                }

                var open = raw.IndexOf('(');
                if (open < 0) continue; // a field
                var close = raw.LastIndexOf(')');
                var head = raw.Substring(0, open).Trim();
                var name = head.Substring(head.LastIndexOfAny(new[] { ' ', '>' }) + 1);
                var args = SplitParams(raw.Substring(open + 1, close - open - 1));
                current.Methods.Add(new JavaMethod
                {
                    Name = name,
                    Static = Regex.IsMatch(head, @"\bstatic\b"),
                    Params = args,
                    VarArgs = args.Length > 0 && args[args.Length - 1].EndsWith("..."),
                });
            }

            return _manifest = classes;
        }

        // Method names of the JDK that the bridge calls on java.util / java.io / java.lang objects. The SDK snapshot
        // cannot vouch for them; they are as stable as the platform.
        static readonly HashSet<string> JdkMethodNames = new HashSet<string>
        {
            "put", "toString", "run", "name", "size", "entrySet", "get", "getKey", "getValue", "hasNext", "next",
            "iterator", "add", "intValue", "longValue", "shortValue", "byteValue", "floatValue", "doubleValue",
            "booleanValue", "charValue", "getClass", "getName", "getMessage", "openStream", "write", "toMap", "close",
        };

        static IEnumerable<string> AndroidSources() =>
            Directory.GetFiles(RepoFile("Runtime/Platform/Android"), "*.cs", SearchOption.AllDirectories).OrderBy(f => f);

        static string[] SplitArgs(string args)
        {
            var parts = new List<string>();
            int depth = 0, start = 0;
            char quote = '\0';
            for (int i = 0; i < args.Length; i++)
            {
                char c = args[i];
                if (quote != '\0')
                {
                    if (c == '\\') i++;
                    else if (c == quote) quote = '\0';
                    continue;
                }

                if (c == '"' || c == '\'') quote = c;
                else if (c == '(' || c == '[' || c == '{') depth++;
                else if (c == ')' || c == ']' || c == '}') depth--;
                else if (c == ',' && depth == 0)
                {
                    parts.Add(args.Substring(start, i - start).Trim());
                    start = i + 1;
                }
            }

            var last = args.Substring(start).Trim();
            if (last.Length > 0 || parts.Count > 0) parts.Add(last);
            return parts.ToArray();
        }

        static string BalancedArgs(string src, int open)
        {
            int depth = 1, i = open;
            bool inString = false;
            for (; i < src.Length && depth > 0; i++)
            {
                char c = src[i];
                if (inString)
                {
                    if (c == '\\') i++;
                    else if (c == '"') inString = false;
                    continue;
                }

                if (c == '"') inString = true;
                else if (c == '(') depth++;
                else if (c == ')') depth--;
            }

            return src.Substring(open, i - 1 - open);
        }

        static string Resolve(string expr, string src)
        {
            expr = expr.Trim();
            var literal = Regex.Match(expr, "^\"([^\"]*)\"$");
            if (literal.Success) return literal.Groups[1].Value;
            var constant = Regex.Match(src, @"\bconst\s+string\s+" + Regex.Escape(expr) + @"\s*=\s*""([^""]*)""");
            return constant.Success ? constant.Groups[1].Value : null;
        }

        sealed class Binding
        {
            public string Var;
            public int Index;
            public string Class;
        }

        static readonly Regex ClassBindingRe =
            new Regex(@"\b(?:var|AndroidJavaClass)\s+(\w+)\s*=\s*new\s+AndroidJavaClass\(\s*([^)]+?)\s*\)");

        /// <summary>Per file: the locals and fields bound to an AndroidJavaClass, with the class they name.</summary>
        static Dictionary<string, List<Binding>> Bindings(Dictionary<string, string> sources)
        {
            var result = new Dictionary<string, List<Binding>>();
            foreach (var kv in sources)
            {
                var list = new List<Binding>();
                foreach (Match m in ClassBindingRe.Matches(kv.Value))
                {
                    var cls = Resolve(m.Groups[2].Value, kv.Value);
                    // A class taken as a parameter (AndroidOptionsMapper.EnumFromInt) is checked through its callers.
                    if (cls == null) cls = "";
                    Assert.That(cls != "" || m.Groups[2].Value == "className", Is.True, Path.GetFileName(kv.Key) + ": cannot resolve the class of " + m.Value);
                    list.Add(new Binding { Var = m.Groups[1].Value, Index = m.Index, Class = cls });
                }

                result[kv.Key] = list;
            }

            return result;
        }

        static Dictionary<string, string> Sources() =>
            AndroidSources().ToDictionary(f => f, f => StripComments(File.ReadAllText(f)));

        [Test]
        public void The_snapshot_and_the_parsers_see_the_known_surface()
        {
            var manifest = Manifest();
            Assert.That(manifest.Keys, Does.Contain("com.bugsee.library.Bugsee")
                .And.Contain("com.bugsee.library.contracts.options.LogLevel"));
            var bugsee = manifest["com.bugsee.library.Bugsee"];
            Assert.That(bugsee.Methods.Count(m => m.Static && m.Name == "launch"), Is.GreaterThanOrEqualTo(4));
            Assert.That(bugsee.Methods.Where(m => m.Name == "deleteCollectedDataOnDevice").Select(m => m.Params.Length),
                Is.EquivalentTo(new[] { 2, 3 }));
            Assert.That(manifest["com.bugsee.library.contracts.options.IssueSeverity"].IsEnum, Is.True);

            var sources = Sources();
            Assert.That(Calls(sources).Count, Is.GreaterThanOrEqualTo(50));
            Assert.That(Calls(sources).Count(c => c.Class == "com.bugsee.library.Bugsee"), Is.GreaterThanOrEqualTo(40));
        }

        [Test]
        public void Every_com_bugsee_library_class_named_in_managed_code_is_in_the_snapshot()
        {
            var manifest = Manifest();
            var missing = new List<string>();
            var seen = 0;
            foreach (var kv in Sources())
            {
                foreach (Match m in Regex.Matches(kv.Value, @"""(com\.bugsee\.library\.[\w.]+)"""))
                {
                    seen++;
                    if (!manifest.ContainsKey(m.Groups[1].Value)) missing.Add(Path.GetFileName(kv.Key) + ": " + m.Groups[1].Value);
                }
            }

            Assert.That(seen, Is.GreaterThanOrEqualTo(10));
            Assert.That(missing, Is.Empty, "Classes not in the Android SDK snapshot");
        }

        sealed class StaticCall
        {
            public string File;
            public string Class;
            public string Name;
            public string[] Args;
        }

        static List<StaticCall> Calls(Dictionary<string, string> sources)
        {
            var bindings = Bindings(sources);
            // Fields (_bugsee) are bound in one file and used in others: resolve them by name across files.
            var fieldClass = bindings.Values.SelectMany(b => b).Where(b => b.Var.StartsWith("_"))
                .GroupBy(b => b.Var).ToDictionary(g => g.Key, g => g.Select(b => b.Class).Distinct().Single());
            var calls = new List<StaticCall>();
            var callRe = new Regex(@"\b(?:\w+\s*\.\s*)*(\w+)\s*\??\s*\.\s*CallStatic(?:<[^>]+>)?\s*\(");
            foreach (var kv in sources)
            {
                foreach (Match m in callRe.Matches(kv.Value))
                {
                    var receiver = m.Groups[1].Value;
                    var args = SplitArgs(BalancedArgs(kv.Value, m.Index + m.Length));
                    var file = Path.GetFileName(kv.Key);
                    var prior = bindings[kv.Key].Where(b => b.Var == receiver && b.Index < m.Index).LastOrDefault();
                    string cls = prior?.Class;
                    if (cls == null) fieldClass.TryGetValue(receiver, out cls);
                    if (cls == "") cls = null;
                    Assert.That(cls != null || (file == "AndroidOptionsMapper.cs" && receiver == "clazz" && Resolve(args[0], kv.Value) == null),
                        Is.True, file + ": the class of '" + receiver + "' in CallStatic is not bound by a visible 'new AndroidJavaClass(...)'");
                    var name = Resolve(args[0], kv.Value);
                    if (cls == null)
                    {
                        continue; // EnumFromInt's parameter class; its callers are added below
                    }

                    if (name == null)
                    {
                        // A method name chosen at run time: the callers pass a literal elsewhere; not checkable here.
                        Assert.That(file, Is.EqualTo("AndroidOptionsMapper.cs"), file + ": CallStatic with a computed method name " + args[0]);
                        continue;
                    }

                    calls.Add(new StaticCall { File = file, Class = cls, Name = name, Args = args.Skip(1).ToArray() });
                }

                // EnumFromInt(<class const>, "<method>", value, default) calls <method>(int) and <method>(int, enum) on the class.
                foreach (Match m in Regex.Matches(kv.Value, @"\bEnumFromInt\(\s*(\w+)\s*,\s*""(\w+)""\s*,"))
                {
                    var cls = Resolve(m.Groups[1].Value, kv.Value);
                    Assert.That(cls, Is.Not.Null, Path.GetFileName(kv.Key) + ": EnumFromInt class " + m.Groups[1].Value);
                    var file = Path.GetFileName(kv.Key);
                    calls.Add(new StaticCall { File = file, Class = cls, Name = m.Groups[2].Value, Args = new[] { "(int)0" } });
                    calls.Add(new StaticCall { File = file, Class = cls, Name = m.Groups[2].Value, Args = new[] { "(int)0", "def" } });
                }
            }

            return calls;
        }

        /// <summary>The java types a managed argument expression can be, or null when it cannot be told from the text.</summary>
        static string[] LiteralTypes(string arg)
        {
            arg = arg.Trim();
            if (arg == "true" || arg == "false") return new[] { "boolean" };
            if (arg.StartsWith("(sbyte)")) return new[] { "byte" };
            if (arg.StartsWith("(int)")) return new[] { "int" };
            if (arg.StartsWith("(long)")) return new[] { "long" };
            if (arg.StartsWith("(float)")) return new[] { "float" };
            if (arg.StartsWith("(double)")) return new[] { "double" };
            if (Regex.IsMatch(arg, "^\"[^\"]*\"$") || Regex.IsMatch(arg, "^[\\w.]+ \\?\\? \"\"$"))
                return new[] { "java.lang.String", "java.lang.CharSequence", "java.lang.Object" };
            return null;
        }

        static bool Accepts(JavaMethod method, string[] args)
        {
            var count = method.Params.Length;
            if (method.VarArgs ? args.Length < count - 1 : args.Length != count) return false;
            for (int i = 0; i < args.Length; i++)
            {
                var types = LiteralTypes(args[i]);
                if (types == null) continue;
                var param = method.Params[Math.Min(i, count - 1)].Replace("...", "").Trim();
                if (!types.Contains(param)) return false;
            }

            return true;
        }

        [Test]
        public void Every_CallStatic_reaches_a_public_static_sdk_method_with_matching_arguments()
        {
            var manifest = Manifest();
            var failures = new List<string>();
            foreach (var call in Calls(Sources()))
            {
                if (!call.Class.StartsWith("com.bugsee.library.")) continue; // UnityWrapper is NativeBindingTests', the rest is the JDK
                if (!manifest.TryGetValue(call.Class, out var cls))
                {
                    failures.Add(call.File + ": " + call.Class + " is not in the snapshot");
                    continue;
                }

                var statics = cls.Methods.Where(m => m.Static && m.Name == call.Name).ToList();
                if (!statics.Any(m => Accepts(m, call.Args)))
                {
                    failures.Add(call.File + ": " + cls.Name + "." + call.Name + "(" + string.Join(", ", call.Args) + ") has no match among: "
                                 + (statics.Count == 0 ? "(no public static method of that name)" : string.Join(" | ", statics)));
                }
            }

            Assert.That(failures, Is.Empty, "Calls the pinned Android SDK does not have:\n" + string.Join("\n", failures));
        }

        [Test]
        public void Every_instance_Call_names_a_method_of_the_sdk_contracts_or_the_jdk()
        {
            var manifest = Manifest();
            var known = new HashSet<string>(manifest.Values.SelectMany(c => c.Methods).Where(m => !m.Static).Select(m => m.Name));
            var failures = new List<string>();
            var seen = 0;
            // Call("name", ...), Call<T>("name", ...) and the helper wrappers that take the method name first.
            var callRe = new Regex(@"(?<![\w])(?:Call|Set|CallVoid|CallObject)(?:<[^>]+>)?\s*\(\s*""(\w+)""");
            foreach (var kv in Sources())
            {
                foreach (Match m in callRe.Matches(kv.Value))
                {
                    seen++;
                    var name = m.Groups[1].Value;
                    if (!known.Contains(name) && !JdkMethodNames.Contains(name))
                        failures.Add(Path.GetFileName(kv.Key) + ": " + name);
                }
            }

            Assert.That(seen, Is.GreaterThanOrEqualTo(80));
            Assert.That(failures, Is.Empty, "Instance methods that are neither in the SDK snapshot nor a known JDK method");
        }

        [Test]
        public void Snapshot_matches_the_pinned_version()
        {
            var header = File.ReadLines(ManifestFile()).First();
            var version = Regex.Match(File.ReadAllText(RepoFile("Tools~/versions.env")), "ANDROID_SDK_VERSION=\"([^\"]+)\"").Groups[1].Value;
            Assert.That(header, Does.Contain(" " + version + " "));
        }
    }
}
